// Inverter run state
// 59: run state
// 0x0000 = standby
// 0x0001 = selfcheck
// 0x0002 = normal
// 0x0003 = alarm
// 0x0004 = fault

msg.baseAddr = 59;

msg.payload = {
    fc: 3,
    unitid: 1,
    address: 59,
    quantity: 1
};

return msg;

// Warning registers
// 101: Warning message word 1
// 102: Warning message word 2

msg.baseAddr = 101;

msg.payload = {
    fc: 3,
    unitid: 1,
    address: 101,
    quantity: 2
};

return msg;

// Fault registers
// 103: Fault information word 1
// 104: Fault information word 2
// 105: Fault information word 3
// 106: Fault information word 4

msg.baseAddr = 103;

msg.payload = {
    fc: 3,
    unitid: 1,
    address: 103,
    quantity: 4
};

return msg;

// Build InverterAlarmState from multiple Modbus reads.
//
// Registers:
// 59      : Run state (0=standby, 1=selfcheck, 2=normal, 3=alarm, 4=fault)
// 101     : Warning message word 1
// 102     : Warning message word 2
// 103     : Fault information word 1
// 104     : Fault information word 2
// 105     : Fault information word 3
// 106     : Fault information word 4

let raw = msg.payload;

// node-red-contrib-modbus often sends { data: [...], buffer: ... }
let data = raw;
if (data && Array.isArray(data.data)) {
    data = data.data;
}

// Skip string errors
if (typeof raw === "string" || !Array.isArray(data)) {
    return null;
}

// Determine which block we just read
let baseAddr = msg.baseAddr;
if (typeof baseAddr !== "number") {
    baseAddr = (msg.modbusRequest && msg.modbusRequest.address);
}
if (typeof baseAddr !== "number") {
    node.warn("InverterAlarmState: missing base address on msg");
    return null;
}

// Fault code definitions from datasheet
const FAULT_CODES = {
    // Word 1 (103)
    "F07": { bit: 7, word: 1, messageKey: "DC_DC_SOFTSTART_FAULT", category: "dc_dc", sourceDevice: "inverter" },
    "F10": { bit: 10, word: 1, messageKey: "AUX_POWER_FAILURE", category: "power", sourceDevice: "inverter" },
    "F13": { bit: 13, word: 1, messageKey: "WORK_MODE_CHANGE", category: "mode", sourceDevice: "inverter" },
    "F17": { bit: 1, word: 2, messageKey: "ACTIVE_BATTERY_HOLD", category: "battery", sourceDevice: "battery" },
    "F18": { bit: 2, word: 2, messageKey: "AC_OVER_CURRENT_HW", category: "over_current", sourceDevice: "inverter" },
    "F20": { bit: 4, word: 2, messageKey: "DC_OVER_CURRENT_HW", category: "over_current", sourceDevice: "pv" },
    "F22": { bit: 6, word: 2, messageKey: "EMERGENCY_STOP", category: "safety", sourceDevice: "inverter" },
    "F23": { bit: 7, word: 2, messageKey: "AC_LEAKAGE_CURRENT", category: "leakage", sourceDevice: "inverter" },
    "F24": { bit: 8, word: 2, messageKey: "DC_INSULATION_FAULT", category: "insulation", sourceDevice: "pv" },
    "F25": { bit: 9, word: 2, messageKey: "AC_ACTIVE_BATT_FAULT", category: "battery", sourceDevice: "battery" },
    "F26": { bit: 10, word: 2, messageKey: "DC_BUS_UNBALANCED", category: "dc_bus", sourceDevice: "inverter" },
    "F29": { bit: 13, word: 2, messageKey: "PARALLEL_CANBUS_FAULT", category: "communication", sourceDevice: "inverter" },
    "F31": { bit: 15, word: 2, messageKey: "SOFT_START_FAILED", category: "startup", sourceDevice: "inverter" },
    "F35": { bit: 3, word: 3, messageKey: "NO_AC_GRID", category: "grid", sourceDevice: "grid" },
    "F37": { bit: 5, word: 3, messageKey: "DCLLC_SOFT_OVER_CUR", category: "over_current", sourceDevice: "inverter" },
    "F39": { bit: 7, word: 3, messageKey: "DCLLC_OVER_CURRENT", category: "over_current", sourceDevice: "inverter" },
    "F40": { bit: 8, word: 3, messageKey: "BATT_OVER_CURRENT", category: "over_current", sourceDevice: "battery" },
    "F41": { bit: 9, word: 3, messageKey: "PARALLEL_SYSTEM_STOP", category: "parallel", sourceDevice: "inverter" },
    "F42": { bit: 10, word: 3, messageKey: "AC_LINE_LOW_VOLTAGE", category: "under_voltage", sourceDevice: "grid" },
    "F46": { bit: 14, word: 3, messageKey: "BACKUP_BATTERY_FAULT", category: "battery", sourceDevice: "battery" },
    "F47": { bit: 15, word: 3, messageKey: "AC_OVER_FREQUENCY", category: "frequency", sourceDevice: "grid" },
    "F48": { bit: 0, word: 4, messageKey: "AC_UNDER_FREQUENCY", category: "frequency", sourceDevice: "grid" },
    "F49": { bit: 1, word: 4, messageKey: "BACKUP_BATTERY_FAULT_2", category: "battery", sourceDevice: "battery" },
    "F56": { bit: 8, word: 4, messageKey: "DC_BUS_LOW_VOLTAGE", category: "under_voltage", sourceDevice: "battery" },
    "F58": { bit: 10, word: 4, messageKey: "BMS_COMM_FAULT", category: "communication", sourceDevice: "bms" },
    "F60": { bit: 12, word: 4, messageKey: "GEN_VOLT_OR_FREQ_FAULT", category: "generator", sourceDevice: "generator" },
    "F61": { bit: 13, word: 4, messageKey: "BUTTON_MANUAL_OFF", category: "manual", sourceDevice: "inverter" },
    "F63": { bit: 15, word: 4, messageKey: "ARC_FAULT", category: "arc", sourceDevice: "pv" },
    "F64": { bit: 0, word: 5, messageKey: "HEATSINK_OVER_TEMP", category: "over_temp", sourceDevice: "inverter" }
};

const WARNING_CODES = {
    "W01": { bit: 0, word: 1, messageKey: "RESERVED", category: "other", sourceDevice: "inverter" },
    "W02": { bit: 1, word: 1, messageKey: "FAN_WARNING", category: "fan", sourceDevice: "inverter" },
    "W03": { bit: 2, word: 1, messageKey: "GRID_PHASE_WRONG", category: "grid", sourceDevice: "grid" },
    "W04": { bit: 3, word: 1, messageKey: "METER_COMM_FAIL", category: "communication", sourceDevice: "inverter" }
};

// Helper function to decode alarms from word
function decodeAlarms(words, codeTable, severity) {
    const alarms = [];
    const now = new Date().toISOString();

    for (const [code, info] of Object.entries(codeTable)) {
        const wordIndex = info.word - 1;
        if (wordIndex >= 0 && wordIndex < words.length) {
            const word = words[wordIndex];
            if (word & (1 << info.bit)) {
                alarms.push({
                    code: parseInt(code.substring(1)),
                    vendorCode: parseInt(code.substring(1)),
                    severity: severity,
                    sourceDevice: info.sourceDevice,
                    category: info.category,
                    messageKey: info.messageKey,
                    messageParams: {},
                    firstOccurredUtc: now,
                    lastOccurredUtc: now,
                    occurrenceCount: 1
                });
            }
        }
    }

    return alarms;
}

// ---- Store partials in flow context ----

// Run state 59
if (baseAddr === 59) {
    flow.set("alarm_part_runstate", {
        runStateRaw: data[0] || 0
    });
}

// Warnings 101-102
else if (baseAddr === 101) {
    flow.set("alarm_part_warnings", {
        warningWord1Raw: data[0] || 0,
        warningWord2Raw: data[1] || 0,
        warningWords: [data[0] || 0, data[1] || 0]
    });
}

// Faults 103-106
else if (baseAddr === 103) {
    flow.set("alarm_part_faults", {
        faultWord1Raw: data[0] || 0,
        faultWord2Raw: data[1] || 0,
        faultWord3Raw: data[2] || 0,
        faultWord4Raw: data[3] || 0,
        faultWords: [data[0] || 0, data[1] || 0, data[2] || 0, data[3] || 0]
    });
}
else {
    return null;
}

// ---- Try to assemble full state ----

const runstatePart = flow.get("alarm_part_runstate");
const warningsPart = flow.get("alarm_part_warnings");
const faultsPart = flow.get("alarm_part_faults");

// Require all parts
if (!runstatePart || !warningsPart || !faultsPart) {
    return null;
}

// Decode active alarms
const warningAlarms = decodeAlarms(warningsPart.warningWords, WARNING_CODES, "warning");
const faultAlarms = decodeAlarms(faultsPart.faultWords, FAULT_CODES, "fault");
const activeAlarms = [...warningAlarms, ...faultAlarms];

// Resolve identifiers
const gatewayId = msg.gatewayId
    || global.get("GATEWAY_ID")
    || env.get("GATEWAY_ID")
    || "EC100-GW-001";

const inverterSN = msg.inverterSerialNumber
    || global.get("INVERTER_SN")
    || env.get("INVERTER_SN")
    || "Unknown";

const state = {
    kind: "InverterAlarmState",
    timestampUtc: new Date().toISOString(),
    gatewayId: gatewayId,
    inverterSerialNumber: inverterSN,

    // Raw registers
    runStateRaw: runstatePart.runStateRaw,
    faultWord1Raw: faultsPart.faultWord1Raw,
    faultWord2Raw: faultsPart.faultWord2Raw,
    faultWord3Raw: faultsPart.faultWord3Raw,
    faultWord4Raw: faultsPart.faultWord4Raw,
    warningWord1Raw: warningsPart.warningWord1Raw,
    warningWord2Raw: warningsPart.warningWord2Raw,

    // Decoded alarms
    activeAlarms: activeAlarms
};

// Clear partials for next cycle
flow.set("alarm_part_runstate", null);
flow.set("alarm_part_warnings", null);
flow.set("alarm_part_faults", null);

// Keep snapshot in flow
flow.set("inverterAlarmSnapshot", state);

// Put result on msg
msg.payload = state;
msg.state = state;

return msg;
